results.content:
1	#!/bin/bash
2	# Initialize a Vite + React + TypeScript + Tailwind + shadcn/ui project
3	# Usage: bash scripts/init-vite.sh <project-name>
4	
5	set -e
6	
7	PROJECT_NAME="${1:-my-site}"
8	
9	# Check Node version
10	NODE_VERSION=$(node -v 2>/dev/null | cut -d'v' -f2 | cut -d'.' -f1)
11	if [ -z "$NODE_VERSION" ] || [ "$NODE_VERSION" -lt 18 ]; then
12	  echo "❌ Error: Node.js 18+ is required. Current: $(node -v 2>/dev/null || echo 'not installed')"
13	  exit 1
14	fi
15	
16	echo "🚀 Creating Vite project: $PROJECT_NAME"
17	
18	# Create Vite project
19	npm create vite@latest "$PROJECT_NAME" -- --template react-ts
20	cd "$PROJECT_NAME"
21	
22	# Create .nvmrc for Node version
23	echo "18" > .nvmrc
24	
25	echo "📦 Installing dependencies..."
26	
27	# Install Tailwind CSS v4 (Vite plugin)
28	npm install -D tailwindcss @tailwindcss/vite
29	
30	# Install animation library
31	npm install framer-motion
32	
33	# Install shadcn/ui base dependencies
34	npm install tailwindcss-animate class-variance-authority clsx tailwind-merge
35	npm install lucide-react
36	npm install @radix-ui/react-slot
37	
38	echo "⚙️ Configuring Tailwind v4..."
39	
40	# No tailwind.config.ts needed in v4 — configuration is done in CSS via @theme
41	
42	# Create base CSS (Tailwind v4 style)
43	cat > src/index.css << 'EOF'
44	@import "tailwindcss";
45	
46	@theme {
47	  --color-border: hsl(var(--border));
48	  --color-input: hsl(var(--input));
49	  --color-ring: hsl(var(--ring));
50	  --color-background: hsl(var(--background));
51	  --color-foreground: hsl(var(--foreground));
52	  --color-primary: hsl(var(--primary));
53	  --color-primary-foreground: hsl(var(--primary-foreground));
54	  --color-secondary: hsl(var(--secondary));
55	  --color-secondary-foreground: hsl(var(--secondary-foreground));
56	  --color-destructive: hsl(var(--destructive));
57	  --color-destructive-foreground: hsl(var(--destructive-foreground));
58	  --color-muted: hsl(var(--muted));
59	  --color-muted-foreground: hsl(var(--muted-foreground));
60	  --color-accent: hsl(var(--accent));
61	  --color-accent-foreground: hsl(var(--accent-foreground));
62	  --color-popover: hsl(var(--popover));
63	  --color-popover-foreground: hsl(var(--popover-foreground));
64	  --color-card: hsl(var(--card));
65	  --color-card-foreground: hsl(var(--card-foreground));
66	  --radius-lg: var(--radius);
67	  --radius-md: calc(var(--radius) - 2px);
68	  --radius-sm: calc(var(--radius) - 4px);
69	}
70	
71	@layer base {
