echo "  cd $PROJECT_NAME"
echo "  npm run dev"
echo ""
echo "Add more components:"
echo "  npx shadcn@latest add [component-name]"
echo "  npx shadcn@latest add --all  # Install all components"
echo ""
echo "Build for production:"
echo "  npm run build"
echo ""

