                  >
                    <X className="w-5 h-5 text-navy" />
                  </button>
                </div>
                <nav className="flex flex-col gap-1">
                  {siteConfig.nav.links.map((link) => (
                    <a
                      key={link.label}
                      href={link.href}
                      onClick={() => setMobileOpen(false)}
