import { useState, useRef, useEffect } from 'react'
import { motion } from 'framer-motion'
import { Search, MapPin, ChevronDown, Navigation } from 'lucide-react'
import { siteConfig } from '@/config/site'

export function Hero() {
  const [searchValue, setSearchValue] = useState('')
  const [locationValue, setLocationValue] = useState('')
  const [insuranceValue, setInsuranceValue] = useState('')
  const [showSuggestions, setShowSuggestions] = useState(false)
  const [filteredSuggestions, setFilteredSuggestions] = useState<string[]>([])
  const searchRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (searchValue.length > 0) {
      const filtered = siteConfig.search.suggestions.filter((s) =>
        s.toLowerCase().includes(searchValue.toLowerCase())
      )
      setFilteredSuggestions(filtered.slice(0, 5))
      setShowSuggestions(filtered.length > 0)
    } else {
      setShowSuggestions(false)
    }
  }, [searchValue])

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) {
        setShowSuggestions(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const handleGeoDetect = () => {
    setLocationValue('Detecting...')
    setTimeout(() => setLocationValue('New York, NY'), 1000)
  }

  return (
    <section className="relative pt-28 sm:pt-36 pb-20 sm:pb-32 overflow-hidden">
      {/* Background atmosphere */}
      <div className="absolute inset-0 -z-10">
        <div
          className="absolute top-0 left-1/2 -translate-x-1/2 w-[1200px] h-[800px] opacity-30"
          style={{
            background:
              'radial-gradient(ellipse at center, rgba(0,102,255,0.15) 0%, rgba(27,20,100,0.08) 40%, transparent 70%)',
          }}
        />
        <div className="absolute top-40 right-0 w-96 h-96 rounded-full opacity-20"
          style={{ background: 'radial-gradient(circle, rgba(0,201,167,0.2) 0%, transparent 70%)' }}
        />
        <div className="absolute bottom-0 left-0 w-80 h-80 rounded-full opacity-15"
          style={{ background: 'radial-gradient(circle, rgba(255,217,48,0.25) 0%, transparent 70%)' }}
        />
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="max-w-3xl mx-auto text-center">
          {/* Badge */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-teal/10 text-teal-dark text-sm font-semibold mb-6"
          >
            <span className="w-2 h-2 rounded-full bg-teal animate-pulse" />
            Free for patients — always
          </motion.div>

          {/* Title */}
          <motion.h1
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="font-display text-4xl sm:text-5xl lg:text-6xl font-bold text-navy tracking-tight leading-[1.1] mb-6"
          >
            Find and book
            <br />
            <span className="relative">
              the care you need
              <svg
                className="absolute -bottom-2 left-0 w-full"
                viewBox="0 0 300 12"
                fill="none"
                preserveAspectRatio="none"
              >
                <path
                  d="M2 8.5C50 2.5 120 2 150 5.5C180 9 250 3 298 6"
                  stroke="#FFD930"
                  strokeWidth="4"
                  strokeLinecap="round"
                />
              </svg>
            </span>
          </motion.h1>

          {/* Subtitle */}
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.3 }}
            className="text-lg sm:text-xl text-text-secondary leading-relaxed mb-10 max-w-2xl mx-auto"
          >
            {siteConfig.hero.subtitle}
          </motion.p>

          {/* Search Bar */}
          <motion.div
            ref={searchRef}
            initial={{ opacity: 0, y: 24 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.4 }}
            className="relative max-w-2xl mx-auto"
          >
            <div className="bg-white rounded-2xl shadow-[0_4px_24px_rgba(27,20,100,0.1),0_1px_4px_rgba(27,20,100,0.05)] border border-border p-2 sm:p-3">
              <div className="flex flex-col sm:flex-row gap-2 sm:gap-3">
                {/* Search input */}
                <div className="relative flex-1">
                  <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4.5 h-4.5 text-text-tertiary" />
                  <input
                    type="text"
                    value={searchValue}
                    onChange={(e) => setSearchValue(e.target.value)}
                    onFocus={() => searchValue && setShowSuggestions(true)}
                    placeholder={siteConfig.search.placeholder}
                    className="w-full pl-10 pr-4 py-3 text-sm bg-surface rounded-xl border-0 focus:outline-none focus:ring-2 focus:ring-blue/30 text-text placeholder:text-text-tertiary"
                  />
                </div>

                {/* Location input */}
                <div className="relative sm:w-48">
                  <MapPin className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4.5 h-4.5 text-text-tertiary" />
                  <input
                    type="text"
                    value={locationValue}
                    onChange={(e) => setLocationValue(e.target.value)}
                    placeholder={siteConfig.search.locationPlaceholder}
                    className="w-full pl-10 pr-9 py-3 text-sm bg-surface rounded-xl border-0 focus:outline-none focus:ring-2 focus:ring-blue/30 text-text placeholder:text-text-tertiary"
                  />
                  <button
                    onClick={handleGeoDetect}
                    className="absolute right-2.5 top-1/2 -translate-y-1/2 p-1 rounded-md hover:bg-surface-alt transition-colors"
                    aria-label="Detect location"
                    title="Detect my location"
                  >
                    <Navigation className="w-3.5 h-3.5 text-blue" />
                  </button>
                </div>

                {/* Insurance select */}
                <div className="relative sm:w-48">
                  <select
                    value={insuranceValue}
                    onChange={(e) => setInsuranceValue(e.target.value)}
                    className="w-full pl-3.5 pr-8 py-3 text-sm bg-surface rounded-xl border-0 focus:outline-none focus:ring-2 focus:ring-blue/30 text-text appearance-none cursor-pointer"
                  >
                    <option value="">{siteConfig.search.insurancePlaceholder}</option>
                    {siteConfig.search.insurances.map((ins) => (
                      <option key={ins} value={ins}>
                        {ins}
                      </option>
                    ))}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary pointer-events-none" />
                </div>

                {/* Search button */}
                <button className="px-6 py-3 bg-blue hover:bg-blue-dark text-white font-semibold text-sm rounded-xl transition-colors flex items-center justify-center gap-2 shrink-0">
                  <Search className="w-4 h-4" />
                  <span className="sm:hidden lg:inline">Search</span>
                </button>
              </div>
            </div>

            {/* Autocomplete dropdown */}
            {showSuggestions && (
              <motion.div
                initial={{ opacity: 0, y: -4 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.15 }}
                className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-[0_8px_32px_rgba(27,20,100,0.12)] border border-border overflow-hidden z-30"
              >
                {filteredSuggestions.map((suggestion, i) => (
                  <button
                    key={suggestion}
                    onClick={() => {
                      setSearchValue(suggestion)
                      setShowSuggestions(false)
                    }}
                    className={`w-full px-5 py-3 text-left text-sm hover:bg-surface transition-colors flex items-center gap-3 ${
                      i !== filteredSuggestions.length - 1 ? 'border-b border-border/50' : ''
                    }`}
                  >
                    <Search className="w-4 h-4 text-text-tertiary shrink-0" />
                    <span className="text-text">{suggestion}</span>
                  </button>
                ))}
              </motion.div>
            )}
          </motion.div>
        </div>
      </div>
    </section>
  )
}

