import { motion } from 'framer-motion'
import { Stethoscope, SmilePlus, Sun, Brain, Eye, Bone } from 'lucide-react'
import { siteConfig } from '@/config/site'

const iconMap: Record<string, React.ElementType> = {
  Stethoscope,
  SmilePlus,
  Sun,
  Brain,
  Eye,
  Bone,
}

const cardColors = [
  { bg: 'bg-blue/8', icon: 'text-blue', hover: 'hover:bg-blue/12' },
  { bg: 'bg-teal/8', icon: 'text-teal', hover: 'hover:bg-teal/12' },
  { bg: 'bg-yellow/15', icon: 'text-yellow-dark', hover: 'hover:bg-yellow/20' },
  { bg: 'bg-navy/8', icon: 'text-navy', hover: 'hover:bg-navy/12' },
  { bg: 'bg-blue/8', icon: 'text-blue-dark', hover: 'hover:bg-blue/12' },
  { bg: 'bg-teal/8', icon: 'text-teal-dark', hover: 'hover:bg-teal/12' },
]

export function Specialties() {
  return (
    <section id="specialties" className="py-20 sm:py-28 bg-surface">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.5 }}
          className="text-center mb-14"
        >
          <h2 className="font-display text-3xl sm:text-4xl font-bold text-navy tracking-tight mb-4">
            Popular specialties
          </h2>
          <p className="text-text-secondary text-lg max-w-lg mx-auto">
            Browse top specialties to find the right provider for you
          </p>
        </motion.div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-5">
          {siteConfig.specialties.map((specialty, i) => {
            const Icon = iconMap[specialty.icon] || Stethoscope
            const colors = cardColors[i % cardColors.length]
            return (
              <motion.a
                key={specialty.title}
                href="#"
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, margin: '-40px' }}
                transition={{ duration: 0.4, delay: i * 0.08 }}
                className={`group flex items-start gap-4 p-5 sm:p-6 rounded-2xl bg-white border border-border/60 ${colors.hover} transition-all duration-200 hover:shadow-[0_4px_20px_rgba(27,20,100,0.08)] hover:-translate-y-0.5 no-underline`}
              >
                <div
                  className={`w-12 h-12 rounded-xl ${colors.bg} flex items-center justify-center shrink-0 transition-transform duration-200 group-hover:scale-110`}
                >
                  <Icon className={`w-5.5 h-5.5 ${colors.icon}`} />
                </div>
                <div>
                  <h3 className="font-display font-semibold text-navy text-base mb-1">
                    {specialty.title}
                  </h3>
                  <p className="text-text-secondary text-sm leading-relaxed">
                    {specialty.description}
                  </p>
                </div>
              </motion.a>
            )
          })}
        </div>
      </div>
    </section>
  )
}

