import { motion } from 'framer-motion'
import { siteConfig } from '@/config/site'

export function HowItWorks() {
  return (
    <section className="py-20 sm:py-28 bg-white relative overflow-hidden">
      {/* Subtle background pattern */}
      <div className="absolute inset-0 -z-10 opacity-[0.03]"
        style={{
          backgroundImage: 'radial-gradient(circle, #1B1464 1px, transparent 1px)',
          backgroundSize: '24px 24px',
        }}
      />

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.5 }}
          className="text-center mb-16"
        >
          <h2 className="font-display text-3xl sm:text-4xl font-bold text-navy tracking-tight mb-4">
            How it works
          </h2>
          <p className="text-text-secondary text-lg max-w-lg mx-auto">
            Three simple steps to get the care you need
          </p>
        </motion.div>

        <div className="relative max-w-4xl mx-auto">
          {/* Connecting line */}
          <div className="hidden md:block absolute top-24 left-[calc(16.67%+24px)] right-[calc(16.67%+24px)] h-0.5 bg-gradient-to-r from-blue via-teal to-yellow" />

          <div className="grid grid-cols-1 md:grid-cols-3 gap-10 md:gap-8">
            {siteConfig.howItWorks.steps.map((step, i) => (
              <motion.div
                key={step.number}
                initial={{ opacity: 0, y: 24 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, margin: '-40px' }}
                transition={{ duration: 0.5, delay: i * 0.15 }}
                className="relative text-center"
              >
                {/* Step number circle */}
                <div className="relative z-10 w-12 h-12 rounded-full bg-white border-2 border-blue mx-auto mb-6 flex items-center justify-center shadow-[0_2px_12px_rgba(0,102,255,0.15)]">
                  <span className="font-display font-bold text-blue text-sm">
                    {step.number}
                  </span>
                </div>

                <h3 className="font-display font-semibold text-navy text-lg mb-3">
                  {step.title}
                </h3>
                <p className="text-text-secondary text-sm leading-relaxed max-w-xs mx-auto">
                  {step.description}
                </p>
              </motion.div>
            ))}
          </div>
        </div>
      </div>
    </section>
  )
}

