import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { ChevronLeft, ChevronRight, Quote } from 'lucide-react'
import { siteConfig } from '@/config/site'

export function Testimonials() {
  const [current, setCurrent] = useState(0)

  const prev = () =>
    setCurrent((c) => (c === 0 ? siteConfig.testimonials.length - 1 : c - 1))
  const next = () =>
    setCurrent((c) => (c === siteConfig.testimonials.length - 1 ? 0 : c + 1))

  return (
    <section className="py-20 sm:py-28 bg-surface relative overflow-hidden">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.5 }}
          className="text-center mb-14"
        >
          <h2 className="font-display text-3xl sm:text-4xl font-bold text-navy tracking-tight mb-4">
            What patients are saying
          </h2>
          <p className="text-text-secondary text-lg max-w-lg mx-auto">
            Real stories from real patients who found care through MedBook
          </p>
        </motion.div>

        <div className="relative max-w-2xl mx-auto">
          <AnimatePresence mode="wait">
            <motion.div
              key={current}
              initial={{ opacity: 0, x: 40 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -40 }}
              transition={{ duration: 0.3 }}
              className="bg-white rounded-2xl p-8 sm:p-10 shadow-[0_2px_16px_rgba(27,20,100,0.06)] border border-border/50"
            >
              <Quote className="w-8 h-8 text-yellow mb-5" />
              <blockquote className="text-text text-lg sm:text-xl leading-relaxed mb-8">
                &ldquo;{siteConfig.testimonials[current].quote}&rdquo;
              </blockquote>
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-navy/10 flex items-center justify-center">
                  <span className="font-display font-bold text-navy text-sm">
                    {siteConfig.testimonials[current].author.charAt(0)}
                  </span>
                </div>
                <div>
                  <div className="font-semibold text-navy text-sm">
                    {siteConfig.testimonials[current].author}
                  </div>
                  <div className="text-text-tertiary text-xs">
                    {siteConfig.testimonials[current].location}
                  </div>
                </div>
              </div>
            </motion.div>
          </AnimatePresence>

          {/* Navigation */}
          <div className="flex items-center justify-center gap-4 mt-8">
            <button
              onClick={prev}
              className="w-10 h-10 rounded-full bg-white border border-border hover:bg-surface transition-colors flex items-center justify-center"
              aria-label="Previous testimonial"
            >
              <ChevronLeft className="w-4 h-4 text-navy" />
            </button>
            <div className="flex gap-2">
              {siteConfig.testimonials.map((_, i) => (
                <button
                  key={i}
                  onClick={() => setCurrent(i)}
                  className={`w-2 h-2 rounded-full transition-all duration-200 ${
                    i === current ? 'bg-blue w-6' : 'bg-border hover:bg-text-tertiary'
                  }`}
                  aria-label={`Go to testimonial ${i + 1}`}
                />
              ))}
            </div>
            <button
              onClick={next}
              className="w-10 h-10 rounded-full bg-white border border-border hover:bg-surface transition-colors flex items-center justify-center"
              aria-label="Next testimonial"
            >
              <ChevronRight className="w-4 h-4 text-navy" />
            </button>
          </div>
        </div>
      </div>
    </section>
  )
}

